package ffdd.opsconsole.finance.application;

import com.fasterxml.jackson.databind.*;
import ffdd.opsconsole.treasury.facade.SupportCommissionReadFacade.Sources;
import ffdd.opsconsole.finance.domain.SupportFundAllocation.*;
import ffdd.opsconsole.finance.domain.SupportFundReplay.*;
import ffdd.opsconsole.shared.config.DateTimeFormatConfig;
import java.math.BigDecimal;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;

/** Treasury F5 cash originals only; global journal closure remains Reader responsibility. */
@Service @RequiredArgsConstructor
public class SupportFundCommissionEvidence {
    private final SupportFundJournalBindingService codec;
    private final ObjectMapper json;
    public record Inputs(Sources sources,List<Map<String,Object>> raw,List<Map<String,Object>> operations,List<Map<String,Object>> parties,List<Map<String,Object>> legs,Map<String,Integer> precisions) {}
    public record Verified(Stamp stamp,List<Point> points,String coveredPhase){public Verified{points=List.copyOf(points);}}
    private static final Set<String> MUTABLE_EVENT=Set.of("status","version","updatedAt","unlockAt","frozenFromStatus");
    public Verified verify(Map<String,Object> op,JsonNode source,JsonNode proof,List<Event> events,Inputs input){
        String phase=text(op.get("phase")),sourceKey=text(op.get("sourceKey"));require(Set.of("RELEASE","REVERSE").contains(phase)&&sourceKey.matches("[1-9][0-9]*"));long eventId;try{eventId=Long.parseLong(sourceKey);}catch(NumberFormatException e){throw failure();}String key=key(eventId,phase);long operationId=number(op.get("id"));
        require(operationId>0&&"SUPPORT_COMMISSION".equals(op.get("businessType"))&&"PRODUCTION".equals(op.get("sourceEnvironment"))&&"nx_commission_event".equals(op.get("sourceTable"))&&key.equals(op.get("operationKey"))&&number(one(input.operations(),"operationKey",key).get("id"))==operationId);
        keys(source,Set.of("schemaVersion","event","ledger","releaseLedger"));keys(proof,Set.of("schemaVersion","cashBefore","cashAfter","eventIds"));require("SUPPORT_COMMISSION_V1".equals(text(source.path("schemaVersion")))&&"SUPPORT_COMMISSION_V1".equals(text(proof.path("schemaVersion"))));require(equal(codec.read(text(op.get("sourceSnapshotJson"))),source)&&equal(codec.read(text(op.get("sourceProofJson"))),proof));
        var event=one(input.sources().events(),"id",eventId);long customer=number(event.get("customerId"));require(customer>0&&number(event.get("id"))==eventId&&zero(event.get("deleted"))&&zero(event.get("userDeleted"))&&zero(event.get("userSandbox")));String asset=text(event.get("asset"));require(Set.of("USDT","UVT").contains(asset));text(event.get("commissionType"));
        var amount=money(event.get(asset.equals("UVT")?"amountNex":"amountUsdt"));require(amount.signum()>0&&money(event.get(asset.equals("UVT")?"amountUsdt":"amountNex")).signum()>=0);
        var captured=source.path("event");require(captured.isObject());require(equal(immutable(captured),immutable(json.valueToTree(normalize(event)))));String status=text(captured.path("status"));require(phase.equals("RELEASE")?Set.of("UNLOCKED","AVAILABLE").contains(status):Set.of("REVERSED","REJECTED","ROLLBACK").contains(status));require(number(captured.path("version"))>=0);stored(time(text(captured.path("createdAt"))),"nx_commission_event.created_at",input);stored(time(text(captured.path("updatedAt"))),"nx_commission_event.updated_at",input);require(!time(text(captured.path("updatedAt"))).isBefore(time(text(captured.path("createdAt")))));
        var ledger=ledger(input,eventId,phase,customer,asset,amount);require(equal(source.path("ledger"),ledger));var expectedEvent=new Event(key,phase.equals("RELEASE")?Action.EARNINGS:Action.CLAWBACK,phase.equals("REVERSE")?new Account(customer,asset,"available"):null,phase.equals("RELEASE")?new Account(customer,asset,"available"):null,phase.equals("REVERSE")?key(eventId,"RELEASE"):null,amount,null);
        require(List.of(expectedEvent).equals(events)&&equal(codec.read(text(op.get("orderedEventsJson"))),json.valueToTree(events))&&equal(proof.path("eventIds"),List.of(key)));
        var parties=input.parties().stream().filter(p->number(p.get("operationId"))==operationId).toList();require(parties.size()==1&&number(parties.get(0).get("customerId"))==customer);var legs=input.legs().stream().filter(l->number(l.get("operationId"))==operationId).toList();require(legs.size()==1);var leg=legs.get(0);String inc=text(leg.get("incarnation"));long revision=number(leg.get("revision"));require(inc.matches("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}")&&revision>0);
        var raws=input.raw().stream().filter(r->inc.equals(r.get("incarnation"))&&number(r.get("revision"))==revision).toList();require(raws.size()==1);var raw=raws.get(0);require("CHANGE".equals(raw.get("observation"))&&number(raw.get("oldUserId"))==customer&&number(raw.get("newUserId"))==customer&&number(raw.get("oldId"))>0&&number(raw.get("oldId"))==number(raw.get("newId"))&&number(raw.get("newVersion"))==number(raw.get("oldVersion"))+1&&time(raw.get("oldCreatedAt")).equals(time(raw.get("newCreatedAt"))));
        wallet(proof.path("cashBefore"),raw,"old",inc,revision-1);wallet(proof.path("cashAfter"),raw,"new",inc,revision);Cash before=cash(raw,"old"),after=cash(raw,"new");require(before.pending().compareTo(after.pending())==0&&before.risk().compareTo(after.risk())==0);var delta=phase.equals("RELEASE")?amount:amount.negate();require(after.usdt().subtract(before.usdt()).compareTo(asset.equals("USDT")?delta:BigDecimal.ZERO)==0&&after.nex().subtract(before.nex()).compareTo(asset.equals("UVT")?delta:BigDecimal.ZERO)==0&&money(ledger.get("balanceAfter")).compareTo(asset.equals("USDT")?after.usdt():after.nex())==0);
        if(phase.equals("REVERSE")){
            var release=ledger(input,eventId,"RELEASE",customer,asset,amount);require(equal(source.path("releaseLedger"),release));var original=one(input.operations(),"operationKey",key(eventId,"RELEASE"));var originalEvents=List.of(new Event(key(eventId,"RELEASE"),Action.EARNINGS,null,new Account(customer,asset,"available"),null,amount,null));var verified=verify(original,codec.read(text(original.get("sourceSnapshotJson"))),codec.read(text(original.get("sourceProofJson"))),originalEvents,input);var originalPoint=verified.points().get(0);require(originalPoint.incarnation().equals(inc)&&originalPoint.revision()<revision&&!time(ledger.get("createdAt")).isBefore(time(release.get("createdAt"))));
        }else require(source.path("releaseLedger").isNull());
        return new Verified(new Stamp(Long.toString(eventId),time(ledger.get("createdAt")),DateTimeFormatConfig.BUSINESS_ZONE.getId(),precision("nx_wallet_ledger.created_at",input)),List.of(new Point(inc,revision,customer,before,after,List.of(key))),eventId+":"+phase);
    }
    public void verifyCoverage(Set<Long> component,Inputs input,Set<String> covered){
        var expected=new HashSet<String>();var ledgerIds=new HashSet<Long>();
        for(var ledger:input.sources().ledgers())if(component.contains(number(ledger.get("customerId")))){
            String no=text(ledger.get("bizNo"));var match=java.util.regex.Pattern.compile("F5-COMMISSION-([1-9][0-9]*)-(RELEASE|REVERSE)").matcher(no);require(match.matches()&&ledgerIds.add(number(ledger.get("id"))));long id;try{id=Long.parseLong(match.group(1));}catch(NumberFormatException e){throw failure();}String phase=match.group(2);require(expected.add(id+":"+phase));var op=one(input.operations(),"operationKey",key(id,phase));var source=codec.read(text(op.get("sourceSnapshotJson")));var proof=codec.read(text(op.get("sourceProofJson")));var event=one(input.sources().events(),"id",id);String asset=text(event.get("asset"));var amount=money(event.get(asset.equals("UVT")?"amountNex":"amountUsdt"));long customer=number(event.get("customerId"));verify(op,source,proof,List.of(new Event(key(id,phase),phase.equals("RELEASE")?Action.EARNINGS:Action.CLAWBACK,phase.equals("REVERSE")?new Account(customer,asset,"available"):null,phase.equals("RELEASE")?new Account(customer,asset,"available"):null,phase.equals("REVERSE")?key(id,"RELEASE"):null,amount,null)),input);
        }
        var operations=new HashSet<String>();for(var op:input.operations())if("SUPPORT_COMMISSION".equals(op.get("businessType"))&&input.parties().stream().anyMatch(p->number(p.get("operationId"))==number(op.get("id"))&&component.contains(number(p.get("customerId")))))require(operations.add(text(op.get("sourceKey"))+":"+text(op.get("phase")))&&expected.contains(text(op.get("sourceKey"))+":"+text(op.get("phase"))));require(expected.equals(covered));
    }
    private Map<String,Object> ledger(Inputs input,long eventId,String phase,long customer,String asset,BigDecimal amount){var l=one(input.sources().ledgers(),"bizNo","F5-COMMISSION-"+eventId+"-"+phase);require(number(l.get("id"))>0&&number(l.get("customerId"))==customer&&asset.equals(l.get("asset"))&&"TEAM_COMMISSION".equals(l.get("bizType"))&&"SUCCESS".equals(l.get("status"))&&zero(l.get("deleted"))&&(phase.equals("RELEASE")?"IN":"OUT").equals(l.get("direction"))&&amount.compareTo(money(l.get("amount")))==0&&money(l.get("balanceAfter")).signum()>=0&&("Commission wallet "+(phase.equals("RELEASE")?"release":"reversal")+" | eventId="+eventId).equals(l.get("remark")));stored(time(l.get("createdAt")),"nx_wallet_ledger.created_at",input);require(!time(l.get("updatedAt")).isBefore(time(l.get("createdAt"))));return l;}
    private static JsonNode immutable(JsonNode value){var copy=value.deepCopy();require(copy.isObject());for(var key:MUTABLE_EVENT)((com.fasterxml.jackson.databind.node.ObjectNode)copy).remove(key);return copy;}
    private void wallet(JsonNode w,Map<String,Object> raw,String side,String incarnation,long revision){keys(w,Set.of("id","customerId","incarnation","revision","version","usdtAvailable","nexAvailable","cregisRiskHeld","pendingWithdraw","sandbox","deleted","createdAt","userSandbox","userDeleted"));require(incarnation.equals(text(w.path("incarnation")))&&number(w.path("revision"))==revision);for(var pair:Map.of("id","Id","customerId","UserId","version","Version","usdtAvailable","UsdtAvailable","nexAvailable","NexAvailable","cregisRiskHeld","CregisRiskHeld","pendingWithdraw","PendingWithdraw","createdAt","CreatedAt").entrySet())require(equal(w.path(pair.getKey()),raw.get(side+pair.getValue())));require(zero(w.path("sandbox"))&&zero(w.path("deleted"))&&zero(w.path("userSandbox"))&&zero(w.path("userDeleted"))&&zero(raw.get(side+"Sandbox"))&&zero(raw.get(side+"IsDeleted")));}
    private static Cash cash(Map<String,Object> r,String side){var c=new Cash(money(r.get(side+"UsdtAvailable")),money(r.get(side+"NexAvailable")),money(r.get(side+"PendingWithdraw")),money(r.get(side+"CregisRiskHeld")));require(c.usdt().signum()>=0&&c.nex().signum()>=0&&c.pending().signum()>=0&&c.risk().signum()>=0);return c;}
    private static Map<String,Object> one(List<Map<String,Object>> rows,String field,Object value){var matches=rows.stream().filter(r->value instanceof Number?number(r.get(field))==number(value):value.equals(r.get(field))).toList();require(matches.size()==1);return matches.get(0);}
    private static int precision(String key,Inputs input){Integer p=input.precisions().get(key);require(p!=null&&p>=0&&p<=6);return p;}
    private static void stored(LocalDateTime time,String key,Inputs input){int unit=(int)Math.pow(10,9-precision(key,input));require(time.getNano()%unit==0);}
    private boolean equal(JsonNode a,Object b){return codec.canonical(a).equals(codec.canonical(b instanceof JsonNode n?n:json.valueToTree(normalize(b))));}
    private static Object normalize(Object v){if(v instanceof LocalDateTime t)return t.toString();if(v instanceof Timestamp t)return t.toLocalDateTime().toString();if(v instanceof Map<?,?> m){var r=new LinkedHashMap<String,Object>();m.forEach((k,x)->r.put(k.toString(),normalize(x)));return r;}if(v instanceof Collection<?> c)return c.stream().map(SupportFundCommissionEvidence::normalize).toList();return v;}
    private static String key(long id,String phase){return "COMMISSION:"+id+":"+phase;}
    private static BigDecimal money(Object v){require(v instanceof Number);var n=new BigDecimal(v.toString());require(n.stripTrailingZeros().scale()<=6);return n;}
    private static long number(Object v){require(v instanceof Number);try{return new BigDecimal(v.toString()).longValueExact();}catch(ArithmeticException e){throw failure();}}
    private static long number(JsonNode v){require(v.isNumber());return number(v.numberValue());}
    private static boolean zero(Object v){return v instanceof Boolean b?!b:number(v)==0;}
    private static boolean zero(JsonNode v){return v.isBoolean()?!v.booleanValue():number(v)==0;}
    private static String text(Object v){require(v instanceof String&&!((String)v).isBlank());return (String)v;}
    private static String text(JsonNode v){require(v.isTextual());return text(v.textValue());}
    private static LocalDateTime time(Object v){if(v instanceof Timestamp t)return t.toLocalDateTime();if(v instanceof LocalDateTime t)return t;if(v instanceof String s){try{return LocalDateTime.parse(s);}catch(java.time.format.DateTimeParseException e){try{return LocalDateTime.parse(s,DateTimeFormatConfig.DATE_TIME_FORMATTER);}catch(java.time.format.DateTimeParseException x){throw failure();}}}throw failure();}
    private static void keys(JsonNode v,Set<String> expected){require(v.isObject());var fields=new HashSet<String>();v.fieldNames().forEachRemaining(fields::add);require(fields.equals(expected));}
    private static void require(boolean v){if(!v)throw failure();}
    private static IllegalArgumentException failure(){return new IllegalArgumentException("Unproven commission cash source");}
}
